// যদি আগে থেকেই কোনো অ্যাপ ব্লকড থাকে, তবে সার্ভিস সচল করা
if (!CycleService.appRules.isEmpty()) {
    startService(new android.content.Intent(this, CycleService.class).setAction("START"));
}
} // onCreate ক্লোজ হলো

// ২. ক্লাসের বডি (Class Body)
private android.widget.ListView listView;
private android.widget.ProgressBar progressBar;
private MyAdapter myAdapter;
private String pendingPkg = "";

private void saveRules() {
    android.content.SharedPreferences.Editor ed = getSharedPreferences("rules", 0).edit();
    ed.clear();
    for (java.util.Map.Entry<String, CycleService.AppRule> entry : CycleService.appRules.entrySet()) {
        CycleService.AppRule r = entry.getValue();
        ed.putString(entry.getKey(), r.blockTimeMs + "|" + r.allowTimeMs + "|" + r.blockStr + "|" + r.allowStr + "|" + r.isCurrentlyBlocked + "|" + r.phaseStartTime);
    }
    ed.apply();
}

private void loadAppList() {
    progressBar.setVisibility(android.view.View.VISIBLE);
    new Thread(() -> {
        android.content.pm.PackageManager pm = getPackageManager();
        android.content.Intent i = new android.content.Intent(android.content.Intent.ACTION_MAIN, null);
        i.addCategory(android.content.Intent.CATEGORY_LAUNCHER);
        java.util.List<android.content.pm.ResolveInfo> list = pm.queryIntentActivities(i, 0);
        java.util.Collections.sort(list, new android.content.pm.ResolveInfo.DisplayNameComparator(pm));

        final java.util.ArrayList<java.util.HashMap<String, Object>> data = new java.util.ArrayList<>();
        for (android.content.pm.ResolveInfo r : list) {
            if (r.activityInfo.packageName.equals(getPackageName())) continue;
            java.util.HashMap<String, Object> m = new java.util.HashMap<>();
            m.put("n", pm.getApplicationLabel(r.activityInfo.applicationInfo).toString());
            m.put("p", r.activityInfo.packageName);
            m.put("i", pm.getApplicationIcon(r.activityInfo.applicationInfo));
            data.add(m);
        }
        runOnUiThread(() -> {
            progressBar.setVisibility(android.view.View.GONE);
            myAdapter = new MyAdapter(data);
            listView.setAdapter(myAdapter);
        });
    }).start();
}

private void showConfirmDialog(final String pkg) {
    String name = ""; 
    try { name = getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(pkg, 0)).toString(); } catch(Exception e) { name = pkg; }
    new android.app.AlertDialog.Builder(this)
        .setTitle("Confirmation")
        .setMessage("Do you want to block internet for " + name + "?")
        .setPositiveButton("Yes", (d, w) -> {
            CycleService.appRules.put(pkg, new CycleService.AppRule());
            saveRules();
            updateService();
        }).setNegativeButton("No", (d, w) -> { if (myAdapter != null) myAdapter.notifyDataSetChanged(); }).show();
}

private void showTimerDialog(final String pkg, String appName) {
    android.widget.ScrollView scroll = new android.widget.ScrollView(this);
    android.widget.LinearLayout base = new android.widget.LinearLayout(this);
    base.setOrientation(1); base.setPadding(50, 40, 50, 40);
    scroll.addView(base);

    android.widget.TextView t1 = new android.widget.TextView(this); 
    t1.setText("This app can use internet.");
    t1.setTextSize(16); t1.setTextColor(0xFF000000); t1.setTypeface(null, android.graphics.Typeface.BOLD); 
    base.addView(t1);

    final android.widget.RadioGroup rgAllow = new android.widget.RadioGroup(this);
    String[] allowLabels = {"1m", "5m", "10m", "15m", "30m"};
    long[] allowMs = {60000, 300000, 600000, 900000, 1800000};
    for (int i=0; i<5; i++) {
        android.widget.RadioButton rb = new android.widget.RadioButton(this); 
        rb.setText(allowLabels[i]); rb.setId(100+i); rgAllow.addView(rb);
    }
    base.addView(rgAllow);

    android.widget.TextView t2 = new android.widget.TextView(this); 
    t2.setText("\nThe app will be blocked from using internet.");
    t2.setTextSize(16); t2.setTextColor(0xFF000000); t2.setTypeface(null, android.graphics.Typeface.BOLD); 
    base.addView(t2);

    final android.widget.RadioGroup rgBlock = new android.widget.RadioGroup(this);
    String[] blockLabels = {"1m", "5m", "10m", "15m", "30m", "1h"};
    long[] blockMs = {60000, 300000, 600000, 900000, 1800000, 3600000};
    for (int i=0; i<6; i++) {
        android.widget.RadioButton rb = new android.widget.RadioButton(this); 
        rb.setText(blockLabels[i]); rb.setId(200+i); rgBlock.addView(rb);
    }
    base.addView(rgBlock);

    // আগের সেট করা টাইম সিলেক্ট করে রাখা (ডিফল্ট 5m)
    CycleService.AppRule rule = CycleService.appRules.get(pkg);
    boolean aFound = false, bFound = false;
    if (rule != null) {
        for(int i=0; i<allowLabels.length; i++) if(allowLabels[i].equals(rule.allowStr)) { rgAllow.check(100+i); aFound=true; }
        for(int i=0; i<blockLabels.length; i++) if(blockLabels[i].equals(rule.blockStr)) { rgBlock.check(200+i); bFound=true; }
    }
    if(!aFound) rgAllow.check(101); // Default 5m
    if(!bFound) rgBlock.check(201); // Default 5m

    new android.app.AlertDialog.Builder(this)
        .setView(scroll)
        .setPositiveButton("Apply", (d, w) -> {
            if (rule != null) {
                int aIdx = rgAllow.getCheckedRadioButtonId()-100;
                int bIdx = rgBlock.getCheckedRadioButtonId()-200;
                rule.allowTimeMs = (aIdx>=0) ? allowMs[aIdx] : 300000; 
                rule.blockTimeMs = (bIdx>=0) ? blockMs[bIdx] : 300000;
                rule.allowStr = (aIdx>=0) ? allowLabels[aIdx] : "5m"; 
                rule.blockStr = (bIdx>=0) ? blockLabels[bIdx] : "5m";

                // Apply চাপলেই ব্লক ফেইজ থেকে সাইকেল শুরু হবে
                rule.isCurrentlyBlocked = false; 
                rule.phaseStartTime = System.currentTimeMillis();

                saveRules();
                updateService();
            }
        })
        .setNegativeButton("Cancel", null)
        .show();
}

class MyAdapter extends android.widget.BaseAdapter {
    java.util.ArrayList<java.util.HashMap<String, Object>> _d;
    MyAdapter(java.util.ArrayList<java.util.HashMap<String, Object>> d) { _d = d; }
    @Override public int getCount() { return _d.size(); }
    @Override public Object getItem(int i) { return _d.get(i); }
    @Override public long getItemId(int i) { return i; }
    @Override public android.view.View getView(int i, android.view.View v, android.view.ViewGroup p) {
        if (v == null) {
            android.widget.LinearLayout root = new android.widget.LinearLayout(MainActivity.this); 
            root.setOrientation(1);

            android.widget.LinearLayout top = new android.widget.LinearLayout(MainActivity.this);
            top.setPadding(25, 30, 25, 10); top.setGravity(16);

            android.widget.ImageView img = new android.widget.ImageView(MainActivity.this); 
            top.addView(img, 110, 110);

            android.widget.TextView t = new android.widget.TextView(MainActivity.this); 
            t.setPadding(35, 0, 0, 0); t.setTextSize(16);
            top.addView(t, new android.widget.LinearLayout.LayoutParams(0, -2, 1f));

            android.widget.Switch s = new android.widget.Switch(MainActivity.this); 
            top.addView(s);

            android.widget.TextView t2 = new android.widget.TextView(MainActivity.this);
            t2.setPadding(170, 0, 25, 30); t2.setTextSize(14); 
            t2.setTextColor(android.graphics.Color.parseColor("#007BFF")); // Blue Color

            root.addView(top); root.addView(t2); v = root;
        }

        java.util.HashMap<String, Object> m = _d.get(i);
        final String pkg = m.get("p").toString();
        final String name = m.get("n").toString();

        android.widget.Switch sw = (android.widget.Switch)((android.view.ViewGroup)((android.view.ViewGroup)v).getChildAt(0)).getChildAt(2);
        android.widget.TextView tv = (android.widget.TextView)((android.view.ViewGroup)v).getChildAt(1);

        ((android.widget.TextView)((android.view.ViewGroup)((android.view.ViewGroup)v).getChildAt(0)).getChildAt(1)).setText(name);
        ((android.widget.ImageView)((android.view.ViewGroup)((android.view.ViewGroup)v).getChildAt(0)).getChildAt(0)).setImageDrawable((android.graphics.drawable.Drawable)m.get("i"));

        sw.setOnCheckedChangeListener(null);
        sw.setChecked(CycleService.appRules.containsKey(pkg));

        if (CycleService.appRules.containsKey(pkg)) {
            tv.setVisibility(android.view.View.VISIBLE);
            CycleService.AppRule r = CycleService.appRules.get(pkg);
            // একদম আপনার চাওয়া UI (দুই লাইন)
            tv.setText("Blocked in " + r.blockStr + ".\nCan use " + r.allowStr + ".");
            // এই সেই হারানো জাদুকরী ক্লিক লিসেনার! 👇
            tv.setOnClickListener(v1 -> showTimerDialog(pkg, name)); 
        } else {
            tv.setVisibility(android.view.View.GONE);
            tv.setOnClickListener(null); // বাগ ফিক্স
        }

        sw.setOnClickListener(view -> {
            if (CycleService.appRules.containsKey(pkg)) { 
                CycleService.appRules.remove(pkg); 
                saveRules(); 
                updateService(); 
            } else { 
                sw.setChecked(false); 
                pendingPkg = pkg; 
                android.content.Intent vi = android.net.VpnService.prepare(MainActivity.this);
                if (vi != null) startActivityForResult(vi, 101); 
                else showConfirmDialog(pkg); 
            }
        });
        return v;
    }
}

private void updateService() {
    startService(new android.content.Intent(this, CycleService.class).setAction(CycleService.appRules.isEmpty() ? "STOP" : "START"));
    if (myAdapter != null) myAdapter.notifyDataSetChanged();
}

@Override protected void onActivityResult(int q, int r, android.content.Intent d) { if(r==RESULT_OK) showConfirmDialog(pendingPkg); }

// সার্ভিস এবং বুট লজিক
public static class BootReceiver extends android.content.BroadcastReceiver {
    @Override public void onReceive(android.content.Context context, android.content.Intent intent) {
        if (android.content.Intent.ACTION_BOOT_COMPLETED.equals(intent.getAction())) {
            android.content.Intent it = new android.content.Intent(context, CycleService.class);
            it.setAction("START");
            if (android.os.Build.VERSION.SDK_INT >= 26) context.startForegroundService(it);
            else context.startService(it);
        }
    }
}

public static class CycleService extends android.net.VpnService {
    public static class AppRule { public long blockTimeMs=0, allowTimeMs=0, phaseStartTime=0; public boolean isCurrentlyBlocked=true; public String blockStr="0m", allowStr="0m"; }
    private android.os.ParcelFileDescriptor vpn = null;
    public static java.util.concurrent.ConcurrentHashMap<String, AppRule> appRules = new java.util.concurrent.ConcurrentHashMap<>();
    private static boolean isRunning = false;

    @Override public int onStartCommand(android.content.Intent it, int f, int id) {
        if (it != null && "STOP".equals(it.getAction())) { stopVpn(); return START_NOT_STICKY; }
        if (appRules.isEmpty()) loadFromPrefs();
        if (appRules.isEmpty()) { stopVpn(); return START_NOT_STICKY; }
        establishVpn();
        if (!isRunning) startTimer();
        return START_STICKY;
    }

    private void loadFromPrefs() {
        android.content.SharedPreferences sp = getSharedPreferences("rules", 0);
        java.util.Map<String, ?> all = sp.getAll();
        for (java.util.Map.Entry<String, ?> entry : all.entrySet()) {
            String[] p = entry.getValue().toString().split("\\|");
            if (p.length >= 6) {
                AppRule r = new AppRule();
                r.blockTimeMs = Long.parseLong(p[0]); r.allowTimeMs = Long.parseLong(p[1]);
                r.blockStr = p[2]; r.allowStr = p[3];
                r.isCurrentlyBlocked = Boolean.parseBoolean(p[4]); r.phaseStartTime = Long.parseLong(p[5]);
                appRules.put(entry.getKey(), r);
            }
        }
    }

    private void startTimer() {
        isRunning = true;
        new Thread(() -> {
            while (isRunning) {
                boolean changed = false; long now = System.currentTimeMillis();
                for (String k : appRules.keySet()) {
                    AppRule r = appRules.get(k);
                    if (r.blockTimeMs > 0) { // যদি 0m না হয়
                        long limit = r.isCurrentlyBlocked ? r.blockTimeMs : r.allowTimeMs;
                        if (now - r.phaseStartTime >= limit) { 
                            r.isCurrentlyBlocked = !r.isCurrentlyBlocked; 
                            r.phaseStartTime = now; 
                            changed = true; 
                        }
                    }
                }
                if (changed) establishVpn();
                try { Thread.sleep(2000); } catch(Exception e) {}
            }
        }).start();
    }

    private void establishVpn() {
        try {
            java.util.ArrayList<String> blk = new java.util.ArrayList<>();
            for (String k : appRules.keySet()) if (appRules.get(k).isCurrentlyBlocked) blk.add(k);
            if (vpn != null) { vpn.close(); vpn = null; }
            if (blk.isEmpty()) { showNotif("Monitoring... (No active blocks)"); return; }
            Builder b = new Builder().setSession("ProtonVPN").addAddress("10.0.0.2", 32).addRoute("0.0.0.0", 0);
            for (String p : blk) try { b.addAllowedApplication(p); } catch(Exception e) {}
            try { b.addDisallowedApplication(getPackageName()); } catch(Exception e) {}
            vpn = b.establish();
            showNotif("VPN is Running…");
        } catch (Exception e) {}
    }

    private void stopVpn() { isRunning = false; try { if(vpn!=null) vpn.close(); vpn=null; } catch(Exception e){} stopForeground(true); stopSelf(); }
    private void showNotif(String m) {
        android.app.NotificationManager nm = (android.app.NotificationManager)getSystemService(NOTIFICATION_SERVICE);
        if (android.os.Build.VERSION.SDK_INT >= 26) nm.createNotificationChannel(new android.app.NotificationChannel("nb","VPN",3));
        startForeground(1, new android.app.Notification.Builder(this,"nb").setSmallIcon(android.R.drawable.ic_lock_lock).setContentTitle("Proton VPN").setContentText(m).build());
    }
}
